"use client";

import { useEffect, useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
	Pagination,
	PaginationContent,
	PaginationEllipsis,
	PaginationItem,
} from "@/components/ui/pagination";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import {
	Table,
	TableBody,
	TableCell,
	TableHead,
	TableHeader,
	TableRow,
} from "@/components/ui/table";
import {
	ColumnDef,
	flexRender,
	getCoreRowModel,
	getPaginationRowModel,
	getSortedRowModel,
	PaginationState,
	SortingState,
	useReactTable,
} from "@tanstack/react-table";
import {
	ChevronDownIcon,
	ChevronLeftIcon,
	ChevronRightIcon,
	ChevronUpIcon,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { usePagination } from "@/registry/ui-basic/hooks/usePagination";

type Item = {
	id: string;
	name: string;
	email: string;
	location: string;
	flag: string;
	status: "Active" | "Inactive" | "Pending";
	balance: number;
};

const columns: ColumnDef<Item>[] = [
	{
		id: "select",
		header: ({ table }) => (
			<Checkbox
				checked={
					table.getIsAllPageRowsSelected() ||
					(table.getIsSomePageRowsSelected() && "indeterminate")
				}
				onCheckedChange={(value) =>
					table.toggleAllPageRowsSelected(!!value)
				}
				aria-label="Select all rows"
			/>
		),
		cell: ({ row }) => (
			<Checkbox
				checked={row.getIsSelected()}
				onCheckedChange={(value) => row.toggleSelected(!!value)}
				aria-label="Select row"
			/>
		),
		size: 28,
		enableSorting: false,
	},
	{
		header: "Name",
		accessorKey: "name",
		cell: ({ row }) => (
			<div className="font-medium">{row.getValue("name")}</div>
		),
		size: 180,
	},
	{
		header: "Email",
		accessorKey: "email",
		size: 200,
	},
	{
		header: "Location",
		accessorKey: "location",
		cell: ({ row }) => (
			<div>
				<span className="text-lg leading-none">{row.original.flag}</span>{" "}
				{row.getValue("location")}
			</div>
		),
		size: 180,
	},
	{
		header: "Status",
		accessorKey: "status",
		cell: ({ row }) => (
			<Badge
				className={cn(
					row.getValue("status") === "Inactive" &&
						"bg-muted-foreground/60 text-primary-foreground"
				)}
			>
				{row.getValue("status")}
			</Badge>
		),
		size: 120,
	},
	{
		header: "Balance",
		accessorKey: "balance",
		cell: ({ row }) => {
			const amount = parseFloat(row.getValue("balance"));
			const formatted = new Intl.NumberFormat("en-US", {
				style: "currency",
				currency: "USD",
			}).format(amount);
			return formatted;
		},
		size: 120,
	},
];

export default function Component() {
	const pageSize = 5;

	const [pagination, setPagination] = useState<PaginationState>({
		pageIndex: 0,
		pageSize: pageSize,
	});

	const [sorting, setSorting] = useState<SortingState>([
		{
			id: "name",
			desc: false,
		},
	]);

	const [data, setData] = useState<Item[]>([]);
	useEffect(() => {
		async function fetchPosts() {
			const res = await fetch(
				"https://raw.githubusercontent.com/origin-space/origin-images/refs/heads/main/users-01_fertyx.json"
			);
			const data = await res.json();
			setData(data);
		}
		fetchPosts();
	}, []);

	const table = useReactTable({
		data,
		columns,
		getCoreRowModel: getCoreRowModel(),
		getSortedRowModel: getSortedRowModel(),
		onSortingChange: setSorting,
		enableSortingRemoval: false,
		getPaginationRowModel: getPaginationRowModel(),
		onPaginationChange: setPagination,
		state: {
			sorting,
			pagination,
		},
	});

	const { pages, showLeftEllipsis, showRightEllipsis } = usePagination({
		currentPage: table.getState().pagination.pageIndex + 1,
		totalPages: table.getPageCount(),
		paginationItemsToDisplay: 5,
	});

	return (
		<div className="space-y-4">
			<div className="bg-background overflow-hidden rounded-md border">
				<Table className="table-fixed">
					<TableHeader>
						{table.getHeaderGroups().map((headerGroup) => (
							<TableRow
								key={headerGroup.id}
								className="hover:bg-transparent"
							>
								{headerGroup.headers.map((header) => {
									return (
										<TableHead
											key={header.id}
											style={{ width: `${header.getSize()}px` }}
											className="h-11"
										>
											{header.isPlaceholder ? null : header.column.getCanSort() ? (
												<div
													className={cn(
														header.column.getCanSort() &&
															"flex h-full cursor-pointer items-center justify-between gap-2 select-none"
													)}
													onClick={header.column.getToggleSortingHandler()}
													onKeyDown={(e) => {
														// Enhanced keyboard handling for sorting
														if (
															header.column.getCanSort() &&
															(e.key === "Enter" ||
																e.key === " ")
														) {
															e.preventDefault();
															header.column.getToggleSortingHandler()?.(
																e
															);
														}
													}}
													tabIndex={
														header.column.getCanSort()
															? 0
															: undefined
													}
												>
													{flexRender(
														header.column.columnDef.header,
														header.getContext()
													)}
													{{
														asc: (
															<ChevronUpIcon
																className="shrink-0 opacity-60"
																size={16}
																aria-hidden="true"
															/>
														),
														desc: (
															<ChevronDownIcon
																className="shrink-0 opacity-60"
																size={16}
																aria-hidden="true"
															/>
														),
													}[
														header.column.getIsSorted() as string
													] ?? null}
												</div>
											) : (
												flexRender(
													header.column.columnDef.header,
													header.getContext()
												)
											)}
										</TableHead>
									);
								})}
							</TableRow>
						))}
					</TableHeader>
					<TableBody>
						{table.getRowModel().rows?.length ? (
							table.getRowModel().rows.map((row) => (
								<TableRow
									key={row.id}
									data-state={row.getIsSelected() && "selected"}
								>
									{row.getVisibleCells().map((cell) => (
										<TableCell key={cell.id}>
											{flexRender(
												cell.column.columnDef.cell,
												cell.getContext()
											)}
										</TableCell>
									))}
								</TableRow>
							))
						) : (
							<TableRow>
								<TableCell
									colSpan={columns.length}
									className="h-24 text-center"
								>
									No results.
								</TableCell>
							</TableRow>
						)}
					</TableBody>
				</Table>
			</div>

			{/* Pagination */}
			<div className="flex items-center justify-between gap-3 max-sm:flex-col">
				{/* Page number information */}
				<p
					className="text-muted-foreground flex-1 text-sm whitespace-nowrap"
					aria-live="polite"
				>
					Page{" "}
					<span className="text-foreground">
						{table.getState().pagination.pageIndex + 1}
					</span>{" "}
					of{" "}
					<span className="text-foreground">{table.getPageCount()}</span>
				</p>

				{/* Pagination buttons */}
				<div className="grow">
					<Pagination>
						<PaginationContent>
							{/* Previous page button */}
							<PaginationItem>
								<Button
									size="icon"
									variant="outline"
									className="disabled:pointer-events-none disabled:opacity-50"
									onClick={() => table.previousPage()}
									disabled={!table.getCanPreviousPage()}
									aria-label="Go to previous page"
								>
									<ChevronLeftIcon size={16} aria-hidden="true" />
								</Button>
							</PaginationItem>

							{/* Left ellipsis (...) */}
							{showLeftEllipsis && (
								<PaginationItem>
									<PaginationEllipsis />
								</PaginationItem>
							)}

							{/* Page number buttons */}
							{pages.map((page) => {
								const isActive =
									page === table.getState().pagination.pageIndex + 1;
								return (
									<PaginationItem key={page}>
										<Button
											size="icon"
											variant={`${isActive ? "outline-solid" : "ghost"}`}
											onClick={() => table.setPageIndex(page - 1)}
											aria-current={isActive ? "page" : undefined}
										>
											{page}
										</Button>
									</PaginationItem>
								);
							})}

							{/* Right ellipsis (...) */}
							{showRightEllipsis && (
								<PaginationItem>
									<PaginationEllipsis />
								</PaginationItem>
							)}

							{/* Next page button */}
							<PaginationItem>
								<Button
									size="icon"
									variant="outline"
									className="disabled:pointer-events-none disabled:opacity-50"
									onClick={() => table.nextPage()}
									disabled={!table.getCanNextPage()}
									aria-label="Go to next page"
								>
									<ChevronRightIcon size={16} aria-hidden="true" />
								</Button>
							</PaginationItem>
						</PaginationContent>
					</Pagination>
				</div>

				{/* Results per page */}
				<div className="flex flex-1 justify-end">
					<Select
						value={table.getState().pagination.pageSize.toString()}
						onValueChange={(value) => {
							table.setPageSize(Number(value));
						}}
						aria-label="Results per page"
					>
						<SelectTrigger
							id="results-per-page"
							className="w-fit whitespace-nowrap"
						>
							<SelectValue placeholder="Select number of results" />
						</SelectTrigger>
						<SelectContent>
							{[5, 10, 25, 50].map((pageSize) => (
								<SelectItem key={pageSize} value={pageSize.toString()}>
									{pageSize} / page
								</SelectItem>
							))}
						</SelectContent>
					</Select>
				</div>
			</div>
			<p className="text-muted-foreground mt-4 text-center text-sm">
				Numeric pagination made with{" "}
				<a
					className="hover:text-foreground underline"
					href="https://tanstack.com/table"
					target="_blank"
					rel="noopener noreferrer"
				>
					TanStack Table
				</a>
			</p>
		</div>
	);
}

import React from "react";

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const badgeVariants = cva(
	"inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2",
	{
		variants: {
			variant: {
				default:
					"border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
				secondary:
					"border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
				destructive:
					"border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
				outline: "text-foreground",
			},
		},
		defaultVariants: {
			variant: "default",
		},
	}
);

export interface BadgeProps
	extends React.HTMLAttributes<HTMLDivElement>,
		VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
	return (
		<div className={cn(badgeVariants({ variant }), className)} {...props} />
	);
}

export { Badge, badgeVariants };

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import { Check } from "lucide-react";

const Checkbox = React.forwardRef<
	React.ElementRef<typeof CheckboxPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>
>(({ className, ...props }, ref) => (
	<CheckboxPrimitive.Root
		ref={ref}
		className={cn(
			"peer h-4 w-4 shrink-0 rounded-sm border border-primary ring-offset-background focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground",
			className
		)}
		{...props}
	>
		<CheckboxPrimitive.Indicator
			className={cn("flex items-center justify-center text-current")}
		>
			<Check className="h-4 w-4" />
		</CheckboxPrimitive.Indicator>
	</CheckboxPrimitive.Root>
));
Checkbox.displayName = CheckboxPrimitive.Root.displayName;

export { Checkbox };

type UsePaginationProps = {
    currentPage: number
    totalPages: number
    paginationItemsToDisplay: number
}

type UsePaginationReturn = {
    pages: number[]
    showLeftEllipsis: boolean
    showRightEllipsis: boolean
}

export function usePagination({
    currentPage,
    totalPages,
    paginationItemsToDisplay,
}: UsePaginationProps): UsePaginationReturn {
    const showLeftEllipsis = currentPage - 1 > paginationItemsToDisplay / 2
    const showRightEllipsis =
        totalPages - currentPage + 1 > paginationItemsToDisplay / 2

    function calculatePaginationRange(): number[] {
        if (totalPages <= paginationItemsToDisplay) {
            return Array.from({ length: totalPages }, (_, i) => i + 1)
        }

        const halfDisplay = Math.floor(paginationItemsToDisplay / 2)
        const initialRange = {
            start: currentPage - halfDisplay,
            end: currentPage + halfDisplay,
        }

        const adjustedRange = {
            start: Math.max(1, initialRange.start),
            end: Math.min(totalPages, initialRange.end),
        }

        if (adjustedRange.start === 1) {
            adjustedRange.end = paginationItemsToDisplay
        }
        if (adjustedRange.end === totalPages) {
            adjustedRange.start = totalPages - paginationItemsToDisplay + 1
        }

        if (showLeftEllipsis) adjustedRange.start++
        if (showRightEllipsis) adjustedRange.end--

        return Array.from(
            { length: adjustedRange.end - adjustedRange.start + 1 },
            (_, i) => adjustedRange.start + i
        )
    }

    const pages = calculatePaginationRange()

    return {
        pages,
        showLeftEllipsis,
        showRightEllipsis,
    }
}
